-- wa-particle: 11 questions
INSERT INTO particle_sets (id, language_id, grammar_point_id, published)
SELECT 'pts-ja-wa-particle', 'lang-ja', g.id, false
FROM grammar_points g
WHERE g.language_id = 'lang-ja' AND g.slug = 'wa-particle'
ON CONFLICT DO NOTHING;

INSERT INTO particle_questions (id, set_id, sentence_id, blank_start, blank_end, answer, also_right, wrong, note, sort_index)
SELECT v.id, 'pts-ja-wa-particle', s.id, v.blank_start, v.blank_end, v.answer, v.also_right, v.wrong, v.note, v.sort_index
FROM (VALUES
  ('pts-ja-wa-particle-q0', '私は医者です。', 1, 2, 'は', ARRAY['が']::text[], ARRAY['の', 'で', 'に']::text[], 'は marks what the sentence is about: "as for me". の would turn it into "my doctor", which is not what the English says.', 0),
  ('pts-ja-wa-particle-q1', '父は医者です。', 1, 2, 'は', ARRAY['が']::text[], ARRAY['の', 'と', 'から']::text[], 'は sets up the topic, my father, and then says something about him. の would link 父 to 医者 as the doctor of my father.', 1),
  ('pts-ja-wa-particle-q2', '空は青い。', 1, 2, 'は', ARRAY['が']::text[], ARRAY['を', 'に', 'へ']::text[], 'は names the topic and the rest describes it. 青い is a description, so it cannot take を.', 2),
  ('pts-ja-wa-particle-q3', '鳥は飛ぶ。', 1, 2, 'は', ARRAY['が']::text[], ARRAY['か', 'から', 'と']::text[], 'は gives a general statement about birds as a topic. と would mean "fly with birds", which is not the English.', 3),
  ('pts-ja-wa-particle-q4', 'これは机です。', 2, 3, 'は', ARRAY['が']::text[], ARRAY['の', 'に', 'へ']::text[], 'これは introduces the thing and then names it. に points to a place or a time, not to what something is.', 4),
  ('pts-ja-wa-particle-q5', 'あれは学校です。', 2, 3, 'は', ARRAY['が']::text[], ARRAY['の', 'で', 'と']::text[], 'は makes あれ the topic and 学校です says what it is. で and と need an action to attach to, and です is not one.', 5),
  ('pts-ja-wa-particle-q6', 'あの犬は大きい。', 3, 4, 'は', ARRAY['が']::text[], ARRAY['を', 'と', 'の']::text[], 'は marks the dog as the topic of the description. 大きい describes, so を does not fit.', 6),
  ('pts-ja-wa-particle-q7', 'あなたは学生ですか。', 3, 4, 'は', ARRAY['が']::text[], ARRAY['の', 'と', 'に']::text[], 'は picks あなた as the topic of the question. の would ask about "your student", a different person.', 7),
  ('pts-ja-wa-particle-q8', '今日は暑い。', 2, 3, 'は', ARRAY['が']::text[], ARRAY['を', 'で', 'と']::text[], 'は makes 今日 the topic: "as for today". で would mean "by" or "at", which breaks 暑い.', 8),
  ('pts-ja-wa-particle-q9', '外は暗い。', 1, 2, 'は', ARRAY['が']::text[], ARRAY['の', 'へ', 'から']::text[], 'は sets outside as the topic and 暗い describes it. から would mean "from outside", which 暗い cannot take here.', 9),
  ('pts-ja-wa-particle-q10', '雪は消えた。', 1, 2, 'は', ARRAY['が']::text[], ARRAY['を', 'へ', 'から']::text[], 'は marks the snow as the topic, and the verb says what happened to it. を would make the snow the object.', 10)
) AS v(id, text, blank_start, blank_end, answer, also_right, wrong, note, sort_index)
CROSS JOIN LATERAL (
  SELECT id FROM sentences
  WHERE language_id = 'lang-ja' AND published AND text = v.text
  ORDER BY created_at, id LIMIT 1
) s
WHERE EXISTS (SELECT 1 FROM particle_sets WHERE id = 'pts-ja-wa-particle')
ON CONFLICT DO NOTHING;

